                if !FORK_EXECUTOR_GLOBAL_DATA.crash_handler.is_null() {
                    let func: ForkHandlerFuncPtr =
                        transmute(FORK_EXECUTOR_GLOBAL_DATA.crash_handler);
                    (func)(
                        signal,
                        info,
                        context,
                        addr_of_mut!(FORK_EXECUTOR_GLOBAL_DATA),
                    );
                }
            },
        }
    }

